109	static inline void uart_bth4_post(FAR sem_t *sem)
110	{
111	  int semcount;
112	
113	  nxsem_get_value(sem, &semcount);
114	  if (semcount < 1)
115	    {
116	      nxsem_post(sem);
117	    }
118	}
