120	static void uart_bth4_pollnotify(FAR struct uart_bth4_s *dev,
121	                                 pollevent_t eventset)
122	{
123	  poll_notify(dev->fds, CONFIG_UART_BTH4_NPOLLWAITERS, eventset);
124	
125	  if ((eventset & POLLIN) != 0)
126	    {
127	      uart_bth4_post(&dev->recvsem);
128	    }
129	}
