131	static int uart_bth4_receive(FAR struct bt_driver_s *drv,
132	                             enum bt_buf_type_e type,
133	                             FAR void *buffer, size_t buflen)
134	{
135	  FAR struct uart_bth4_s *dev = drv->priv;
136	  int ret = buflen;
137	  irqstate_t flags;
138	  uint8_t htype;
139	
140	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
141	
142	  if (circbuf_space(&dev->circbuf) >=
143	      buflen + H4_HEADER_SIZE)
144	    {
145	      if (type == BT_EVT)
146	        {
147	          htype = H4_EVT;
148	        }
149	      else if (type == BT_ACL_IN)
150	        {
151	          htype = H4_ACL;
152	        }
153	      else if (type == BT_ISO_IN)
154	        {
155	          htype = H4_ISO;
156	        }
157	      else
158	        {
159	          ret = -EINVAL;
160	        }
161	
162	      if (ret >= 0)
163	        {
164	          circbuf_write(&dev->circbuf, &htype, H4_HEADER_SIZE);
165	          circbuf_write(&dev->circbuf, buffer, buflen);
166	          uart_bth4_pollnotify(dev, POLLIN);
167	        }
168	    }
169	  else
170	    {
171	      ret = -ENOMEM;
172	    }
173	
174	  spin_unlock_irqrestore_nopreempt(&dev->lock, flags);
175	  return ret;
176	}
