237	static ssize_t uart_bth4_read(FAR struct file *filep,
238	                              FAR char *buffer,
239	                              size_t buflen)
240	{
241	  FAR struct inode *inode = filep->f_inode;
242	  FAR struct uart_bth4_s *dev = inode->i_private;
243	  irqstate_t flags;
244	  ssize_t nread;
245	
246	  flags = spin_lock_irqsave(&dev->lock);
247	
248	  for (; ; )
249	    {
250	      nread = circbuf_read(&dev->circbuf, buffer, buflen);
251	      if (nread != 0 || (filep->f_oflags & O_NONBLOCK))
252	        {
253	          break;
254	        }
255	
256	      while (circbuf_is_empty(&dev->circbuf))
257	        {
258	          spin_unlock_irqrestore(&dev->lock, flags);
259	          nxsem_wait_uninterruptible(&dev->recvsem);
260	          flags = spin_lock_irqsave(&dev->lock);
261	        }
262	    }
263	
264	  spin_unlock_irqrestore(&dev->lock, flags);
265	  return nread;
266	}
