390	static int uart_bth4_poll(FAR struct file *filep, FAR struct pollfd *fds,
391	                          bool setup)
392	{
393	  FAR struct inode *inode = filep->f_inode;
394	  FAR struct uart_bth4_s *dev = inode->i_private;
395	  pollevent_t eventset = 0;
396	  irqstate_t flags;
397	  int ret = 0;
398	  int i;
399	
400	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
401	
402	  if (setup)
403	    {
404	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
405	        {
406	          /* Find an available slot */
407	
408	          if (!dev->fds[i])
409	            {
410	              /* Bind the poll structure and this slot */
411	
412	              dev->fds[i] = fds;
413	              fds->priv   = &dev->fds[i];
414	              break;
415	            }
416	        }
417	
418	      if (i >= CONFIG_UART_BTH4_NPOLLWAITERS)
419	        {
420	          fds->priv = NULL;
421	          ret = -EBUSY;
422	        }
423	
424	      if (!circbuf_is_empty(&dev->circbuf))
425	        {
426	          eventset |= POLLIN;
427	        }
428	
429	      eventset |= POLLOUT;
430	
431	      poll_notify(&fds, 1, eventset);
432	    }
433	  else if (fds->priv != NULL)
434	    {
435	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
436	        {
437	          if (fds == dev->fds[i])
438	            {
439	              dev->fds[i] = NULL;
440	              fds->priv = NULL;
441	              break;
442	            }
443	        }
444	    }
445	
446	  spin_unlock_irqrestore_nopreempt(&dev->lock, flags);
447	  return ret;
448	}
