454	int uart_bth4_register(FAR const char *path, FAR struct bt_driver_s *drv)
455	{
456	  FAR struct uart_bth4_s *dev;
457	  int ret;
458	
459	  dev = (FAR struct uart_bth4_s *)
460	        kmm_zalloc(sizeof(struct uart_bth4_s));
461	  if (dev == NULL)
462	    {
463	      return -ENOMEM;
464	    }
465	
466	  ret = circbuf_init(&dev->circbuf, NULL,
467	                     CONFIG_UART_BTH4_RXBUFSIZE);
468	  if (ret < 0)
469	    {
470	      kmm_free(dev);
471	      return -ENOMEM;
472	    }
473	
474	  dev->drv     = drv;
475	  drv->receive = uart_bth4_receive;
476	  drv->priv    = dev;
477	
478	  nxmutex_init(&dev->sendlock);
479	  nxmutex_init(&dev->openlock);
480	  spin_lock_init(&dev->lock);
481	  nxsem_init(&dev->recvsem, 0, 0);
482	
483	  ret = register_driver(path, &g_uart_bth4_ops, 0666, dev);
484	  if (ret < 0)
485	    {
486	      nxmutex_destroy(&dev->sendlock);
487	      nxmutex_destroy(&dev->openlock);
488	      nxsem_destroy(&dev->recvsem);
489	      circbuf_uninit(&dev->circbuf);
490	      kmm_free(dev);
491	    }
492	
493	  return ret;
494	}
