90	static int h4_send_data(int fd, uint8_t* buf, int count)
91	{
92	    int ret, nwritten = 0;
93	
94	    while (nwritten != count) {
95	        ret = write(fd, buf + nwritten, count - nwritten);
96	        if (ret < 0) {
97	            if (errno == EAGAIN) {
98	                usleep(1000);
99	                continue;
100	            } else
101	                return ret;
102	        }
103	
104	        nwritten += ret;
105	    }
106	
107	    return nwritten;
108	}
