110	static struct net_buf* get_rx(const uint8_t* buf)
111	{
112	    bool discardable = false;
113	    k_timeout_t timeout = K_FOREVER;
114	
115	    switch (buf[0]) {
116	    case BT_HCI_H4_EVT:
117	        if (buf[1] == BT_HCI_EVT_LE_META_EVENT && (buf[3] == BT_HCI_EVT_LE_ADVERTISING_REPORT)) {
118	            discardable = true;
119	            timeout = K_NO_WAIT;
120	        }
121	
122	        return bt_buf_get_evt(buf[1], discardable, timeout);
123	    case BT_HCI_H4_ACL:
124	        return bt_buf_get_rx(BT_BUF_ACL_IN, K_FOREVER);
125	    case BT_HCI_H4_ISO:
126	        if (IS_ENABLED(CONFIG_BT_ISO)) {
127	            return bt_buf_get_rx(BT_BUF_ISO_IN, K_FOREVER);
128	        }
129	        break;
130	    default:
131	        BT_LOGE("RX unknown packet type: %u", buf[0]);
132	        break;
133	    }
134	
135	    return NULL;
136	}
