138	static int32_t hci_packet_complete(const uint8_t* buf, uint16_t buf_len)
139	{
140	    uint16_t payload_len = 0;
141	    const uint8_t type = buf[0];
142	    uint8_t header_len = sizeof(type);
143	    const uint8_t* hdr = &buf[sizeof(type)];
144	
145	    switch (type) {
146	    case BT_HCI_H4_CMD: {
147	        const struct bt_hci_cmd_hdr* cmd = (const struct bt_hci_cmd_hdr*)hdr;
148	
149	        if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
150	            return 0;
151	        }
152	
153	        /* Parameter Total Length */
154	        payload_len = cmd->param_len;
155	        header_len += BT_HCI_CMD_HDR_SIZE;
156	        break;
157	    }
158	    case BT_HCI_H4_ACL: {
159	        const struct bt_hci_acl_hdr* acl = (const struct bt_hci_acl_hdr*)hdr;
160	
161	        if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
162	            return 0;
163	        }
164	
165	        /* Data Total Length */
166	        payload_len = sys_le16_to_cpu(acl->len);
167	        header_len += BT_HCI_ACL_HDR_SIZE;
168	        break;
169	    }
170	    case BT_HCI_H4_SCO: {
171	        const struct bt_hci_sco_hdr* sco = (const struct bt_hci_sco_hdr*)hdr;
172	
173	        if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
174	            return 0;
175	        }
176	
177	        /* Data_Total_Length */
178	        payload_len = sco->len;
179	        header_len += BT_HCI_SCO_HDR_SIZE;
180	        break;
181	    }
182	    case BT_HCI_H4_EVT: {
183	        const struct bt_hci_evt_hdr* evt = (const struct bt_hci_evt_hdr*)hdr;
184	
185	        if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
186	            return 0;
187	        }
188	
189	        /* Parameter Total Length */
190	        payload_len = evt->len;
191	        header_len += BT_HCI_EVT_HDR_SIZE;
192	        break;
193	    }
194	    case BT_HCI_H4_ISO: {
195	        const struct bt_hci_iso_hdr* iso = (const struct bt_hci_iso_hdr*)hdr;
196	
197	        if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
198	            return 0;
199	        }
200	
201	        /* ISO_Data_Load_Length parameter */
202	        payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
203	        header_len += BT_HCI_ISO_HDR_SIZE;
204	        break;
205	    }
206	    /* If no valid packet type found */
207	    default:
208	        BT_LOGE("H4: Unknown packet type 0x%02x", type);
209	        return -1;
210	    }
211	
212	    /* Request more data */
213	    if (buf_len < header_len + payload_len) {
214	        return 0;
215	    }
216	
217	    return (int32_t)header_len + payload_len;
218	}
