220	static void bt_sal_hci_transport_recv(void)
221	{
222	    struct h4_data* h4 = bt_dev->data;
223	    static uint8_t frame[1026];
224	    struct net_buf* buf;
225	    size_t buf_tailroom;
226	    size_t buf_add_len;
227	    ssize_t len;
228	    const uint8_t* frame_start = frame;
229	    static ssize_t frame_size = 0;
230	
231	    len = read(h4->fd, frame + frame_size, sizeof(frame) - frame_size);
232	    if (len < 0) {
233	        BT_LOGE("Reading hci failed, errno %d", errno);
234	        close(h4->fd);
235	        h4->fd = -1;
236	        return;
237	    }
238	
239	    frame_size += len;
240	
241	    while (frame_size > 0) {
242	        const uint8_t* buf_add;
243	        const uint8_t packet_type = frame_start[0];
244	        const int32_t decoded_len = hci_packet_complete(frame_start, frame_size);
245	
246	        if (decoded_len == -1) {
247	            BT_LOGE("HCI Packet type is invalid, length could not be decoded");
248	            frame_size = 0; /* Drop buffer */
249	            break;
250	        }
251	
252	        if (decoded_len == 0) {
253	            if (frame_size == sizeof(frame)) {
254	                BT_LOGE("HCI Packet is too big for frame");
255	                frame_size = 0; /* Drop buffer */
256	                break;
257	            }
258	            if (frame_start != frame) {
259	                memmove(frame, frame_start, frame_size);
260	            }
261	            /* Read more */
262	            break;
263	        }
264	
265	        buf_add = frame_start + sizeof(packet_type);
266	        buf_add_len = decoded_len - sizeof(packet_type);
267	
268	        buf = get_rx(frame_start);
269	
270	        frame_size -= decoded_len;
271	        frame_start += decoded_len;
272	
273	        if (!buf) {
274	            BT_LOGD("Discard adv report due to insufficient buf");
275	            continue;
276	        }
277	
278	        buf_tailroom = net_buf_tailroom(buf);
279	        if (buf_tailroom < buf_add_len) {
280	            BT_LOGE("Not enough space in buffer %zu/%zu", buf_add_len,
281	                buf_tailroom);
282	            net_buf_unref(buf);
283	            continue;
284	        }
285	
286	        net_buf_add_mem(buf, buf_add, buf_add_len);
287	
288	        h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
289	        h4->recv(bt_dev, buf, h4->hci_data);
290	    }
291	}
