327	static int h4_open(const struct device* dev, bt_hci_recv_t recv, void* hci_data)
328	{
329	    int fd;
330	    struct h4_data* h4;
331	
332	    syslog(LOG_ERR, "BTDIAG h4_open: opening %s\n", CONFIG_BT_UART_ON_DEV_NAME);
333	    fd = open(CONFIG_BT_UART_ON_DEV_NAME, O_RDWR | O_BINARY | O_CLOEXEC);
334	    syslog(LOG_ERR, "BTDIAG h4_open: open ret=%d errno=%d\n", fd, errno);
335	    if (fd < 0) {
336	        BT_LOGE("H4: Failed to open %s: %d", CONFIG_BT_UART_ON_DEV_NAME, errno);
337	        return fd;
338	    }
339	
340	    h4 = dev->data;
341	    h4->fd = fd;
342	    h4->recv = recv;
343	    h4->hci_data = hci_data;
344	
345	    bt_dev = dev;
346	    BT_LOGE("H4: %s opened as fd:%d", CONFIG_BT_UART_ON_DEV_NAME, h4->fd);
347	
348	    hci_handle = service_loop_poll_fd(h4->fd, POLL_READABLE, hci_poll_recv, NULL);
349	    syslog(LOG_ERR, "BTDIAG h4_open: poll setup %s\n",
350	           hci_handle ? "ok" : "FAILED");
351	    if (!hci_handle) {
352	        BT_LOGD("hci fd:%d add poll failed", h4->fd);
353	        return -1;
354	    }
355	
356	    return 0;
357	}
358	
359	static int h4_send(const struct device* dev, struct net_buf* buf)
360	{
361	    int len;
362	    int ret;
363	    struct h4_data* h4 = bt_dev->data;
364	
365	    switch (bt_buf_get_type(buf)) {
366	    case BT_BUF_ACL_OUT:
367	        net_buf_push_u8(buf, BT_HCI_H4_ACL);
368	        break;
369	    case BT_BUF_CMD:
370	        net_buf_push_u8(buf, BT_HCI_H4_CMD);
371	        break;
372	    case BT_BUF_ISO_OUT:
373	        if (IS_ENABLED(CONFIG_BT_ISO)) {
374	            net_buf_push_u8(buf, BT_HCI_H4_ISO);
375	            break;
376	        }
377	    default:
378	        BT_LOGE("Unknown buffer type");
379	        return -EINVAL;
380	    }
381	
382	    h4_data_dump("BT TX", buf->data[0], buf->data, buf->len);
383	
384	    len = buf->len;
385	    ret = h4_send_data(h4->fd, buf->data, buf->len);
386	    if (ret != len) {
387	        BT_LOGE("H4: Failed to send %u bytes: %d", len, ret);
388	        ret = -EINVAL;
389	    }
390	
391	    net_buf_unref(buf);
392	
393	    return ret < 0 ? ret : 0;
394	}
