280	static FAR uint8_t *bt_slip_unslip_byte(FAR uint8_t *packet,
281	                                        FAR uint8_t *byte)
282	{
283	  uint8_t offset = 0;
284	
285	  if (packet[0] != SLIP_ESC)
286	    {
287	      *byte = packet[0];
288	      return packet;
289	    }
290	
291	  switch (packet[1])
292	    {
293	    case SLIP_ESC_DELIM:
294	      *byte = SLIP_DELIMITER;
295	      offset = 1;
296	      break;
297	    case SLIP_ESC_ESC:
298	      *byte = SLIP_ESC;
299	      offset = 1;
300	      break;
301	    default:
302	      wlerr("err: invalid escape byte %x\n", *byte);
303	      return NULL;
304	    }
305	
306	  packet += offset;
307	  return packet;
308	}
309	
310	static uint8_t *bt_slip_slip_byte(FAR uint8_t *packet, FAR uint8_t byte)
311	{
312	  uint8_t offset = 1;
313	
314	  switch (byte)
315	    {
316	    case SLIP_DELIMITER:
317	      packet[0] = SLIP_ESC;
318	      packet[1] = SLIP_ESC_DELIM;
319	      offset = 2;
320	      break;
321	    case SLIP_ESC:
322	      packet[0] = SLIP_ESC;
323	      packet[1] = SLIP_ESC_ESC;
324	      offset = 2;
325	      break;
326	    default:
327	      packet[0] = byte;
328	      break;
329	    }
330	
331	  packet += offset;
332	  return packet;
333	}
334	
335	static void bt_slip_retx_work(FAR void *arg)
336	{
337	  FAR struct sliphci_s *priv = arg;
338	  FAR struct unack_frame_s *frame;
339	  size_t size;
340	
341	  if (priv->linkstate != BT_SLIP_ACTIVE)
342	    {
343	      wlerr("err: linkstate:%d not active", priv->linkstate);
344	      return;
345	    }
346	
347	  size = bt_slip_unack_size(priv);
348	  while (size > 0)
349	    {
350	      frame = (FAR struct unack_frame_s *)bt_slip_unack_dtor(priv);
351	      bt_slip_send(&priv->dev, frame->type, frame->data, frame->pktlen);
352	      size--;
353	    }
354	}
