356	static bool bt_slip_reliable_packet(uint8_t type)
357	{
358	  switch (type)
359	    {
360	    case HCI_COMMAND_PKT:
361	    case HCI_ACLDATA_PKT:
362	    case HCI_EVENT_PKT:
363	    case HCI_ISODATA_PKT:
364	      return true;
365	    default:
366	      return false;
367	    }
368	}
369	
370	static int bt_slip_send_packet(FAR struct sliphci_s *priv, uint8_t type,
371	                               FAR const uint8_t *payload, size_t len)
372	{
373	  uint8_t packet[CONFIG_BLUETOOTH_SLIP_TXBUFSIZE];
374	  uint8_t header[BT_SLIP_HEADER_LEN];
375	  FAR uint8_t *pend;
376	  uint16_t checksum = 0;
377	  int index;
378	
379	  memset(header, 0, sizeof(header));
380	  if (bt_slip_reliable_packet(type))
381	    {
382	      BT_SLIP_SET_RELIABLE(header);
383	      BT_SLIP_SET_SEQ(header, priv->txseq);
384	      BT_SLIP_SEQ_INCR(priv->txseq);
385	    }
386	
387	  BT_SLIP_SET_ACK(header, priv->txack);
388	  BT_SLIP_SET_TYPE(header, type);
389	  BT_SLIP_SET_LEN(header, len);
390	
391	  if (priv->dipresent)
392	    {
393	      BT_SLIP_SET_DIC(header);
394	    }
395	
396	  /* Set head checksum */
397	
398	  BT_SLIP_SET_HDRCHECKSUM(header);
399	  pend = packet;
400	
401	  /* Put SLIP start */
402	
403	  *pend++ = SLIP_DELIMITER;
404	
405	  /* Put h5 header */
406	
407	  if (priv->dipresent)
408	    {
409	      checksum = crc16ccittpart(header, BT_SLIP_HEADER_LEN, 0xffff);
410	    }
411	
412	  for (index = 0; index < BT_SLIP_HEADER_LEN; index++)
413	    {
414	      pend = bt_slip_slip_byte(pend, header[index]);
415	    }
416	
417	  /* Put h5 payload */
418	
419	  if (priv->dipresent)
420	    {
421	      checksum = crc16ccittpart(payload, len, checksum);
422	    }
423	
424	  for (index = 0; index < len; index++)
425	    {
426	      pend = bt_slip_slip_byte(pend, payload[index]);
427	    }
428	
429	  /* Put crc */
430	
431	  if (priv->dipresent)
432	    {
433	      checksum = bt_slip_bit16_reverse(checksum);
434	      pend = bt_slip_slip_byte(pend, checksum >> 8);
435	      pend = bt_slip_slip_byte(pend, checksum & 0xff);
436	    }
437	
438	  /* Put SLIP end */
439	
440	  *pend++ = SLIP_DELIMITER;
441	
442	  wlinfo("tx t:%d l:%d s:%d a:%d checksum:0x%04x \n",
443	         BT_SLIP_GET_PKT_TYPE(header), BT_SLIP_GET_LEN(header),
444	         BT_SLIP_GET_SEQ(header), BT_SLIP_GET_ACK(header), checksum);
445	
446	  return priv->drv->send(priv->drv, type, packet, pend - packet);
447	}
