467	
468	static int bt_slip_link_packet_hanlde(FAR struct sliphci_s *priv,
469	                                      FAR const uint8_t *header,
470	                                      size_t len)
471	{
472	  FAR const uint8_t *payload = header + BT_SLIP_HEADER_LEN;
473	  int ret = len;
474	
475	  if (memcmp(payload, g_sync_req, ARRAY_SIZE(g_sync_req)) == 0)
476	    {
477	      bt_slip_send_link_control(priv, g_sync_rsp, ARRAY_SIZE(g_sync_rsp));
478	    }
479	  else if (memcmp(payload, g_sync_rsp, ARRAY_SIZE(g_sync_rsp)) == 0)
480	    {
481	      wlinfo("h5: initialized");
482	      priv->linkstate = BT_SLIP_INITIALIZED;
483	      bt_slip_send_link_control(priv, g_conf_req, ARRAY_SIZE(g_conf_req));
484	    }
485	  else if (memcmp(payload, g_conf_req, ARRAY_SIZE(g_conf_req) - 1) == 0)
486	    {
487	      bt_slip_send_link_control(priv, g_conf_rsp, ARRAY_SIZE(g_conf_rsp));
488	      bt_slip_send_link_control(priv, g_conf_req, ARRAY_SIZE(g_conf_req));
489	    }
490	  else if (memcmp(payload, g_conf_rsp, ARRAY_SIZE(g_conf_rsp)) == 0)
491	    {
492	      if (BT_SLIP_GET_LEN(header) > 2)
493	        {
494	          priv->txwin = BT_SLIP_GET_TXWIN(payload);
495	          priv->dipresent = BT_SLIP_IS_DIC(payload);
496	          wlinfo("h5 txwin:%d, dipresent:%d", priv->txwin, priv->dipresent);
497	        }
498	
499	      if (priv->txwin > CONFIG_BLUETOOTH_SLIP_TXWIN)
500	        {
501	          wlerr("err: txwin(%d) overflow(%d)", priv->txwin,
502	                CONFIG_BLUETOOTH_SLIP_TXWIN);
503	          return ret;
504	        }
505	
506	      if (priv->linkstate == BT_SLIP_ACTIVE)
507	        {
508	          return ret;
509	        }
510	
511	      wlinfo("h5: active");
512	      priv->linkstate = BT_SLIP_ACTIVE;
513	      nxsem_post(&priv->sem);
514	    }
515	  else
516	    {
517	      ret = -EINVAL;
518	    }
519	
520	  return ret;
521	}
522	
523	static void bt_slip_unack_handle(FAR struct sliphci_s *priv)
524	{
525	  size_t to_remove;
526	  uint8_t seq;
527	
528	  to_remove = bt_slip_unack_size(priv);
529	  if (to_remove == 0)
530	    {
531	      return;
532	    }
533	
534	  seq = priv->txseq;
535	
536	  do
537	    {
538	      if (priv->rxack == seq)
539	        {
540	          break;
541	        }
542	
543	      seq = (seq - 1) & 0x07;
544	    }
545	  while (--to_remove > 0);
546	
547	  if (seq != priv->rxack)
548	    {
549	      wlerr("err: seq:%d != rxack:%d", seq, priv->rxack);
550	      return;
551	    }
552	
553	  while (to_remove > 0)
554	    {
555	      bt_slip_unack_dtor(priv);
556	
557	      /* When it was blocked by full tx window, we needs to notifiy
558	       * bt_slip_send.
559	       */
560	
561	      if (bt_slip_unack_size(priv) == priv->txwin - 1)
562	        {
563	          int semcount;
564	
565	          if (nxsem_get_value(&priv->sem, &semcount) >= 0)
566	            {
567	              while (semcount++ <= 0)
568	                {
569	                  nxsem_post(&priv->sem);
570	                }
571	            }
572	        }
573	
574	      to_remove--;
575	    }
576	
577	  to_remove = bt_slip_unack_size(priv);
578	  if (!to_remove)
579	    {
580	      work_cancel(HPWORK, &priv->retxworker);
581	    }
582	}
