584	static int bt_slip_hci_packet_handle(FAR struct bt_driver_s *dev,
585	                                     uint8_t type, FAR void *data,
586	                                     size_t len)
587	{
588	  enum bt_buf_type_e var;
589	
590	  if (len < 1)
591	    {
592	      return -EINVAL;
593	    }
594	
595	  switch (type)
596	    {
597	    case HCI_EVENT_PKT:
598	      var = BT_EVT;
599	      break;
600	    case HCI_ACLDATA_PKT:
601	      var = BT_ACL_IN;
602	      break;
603	    case HCI_ISODATA_PKT:
604	      var = BT_ISO_IN;
