613	static int bt_slip_packet_receive(FAR struct sliphci_s *priv,
614	                             FAR uint8_t *header, size_t len)
615	{
616	  FAR uint8_t *payload = header + BT_SLIP_HEADER_LEN;
617	  int ret;
618	
619	  if (BT_SLIP_IS_RELIABLE(header))
620	    {
621	      BT_SLIP_SEQ_INCR(priv->txack);
622	      bt_slip_send_ack(priv);
623	    }
624	
625	  priv->rxack = BT_SLIP_GET_ACK(header);
626	  bt_slip_unack_handle(priv);
627	
628	  switch (BT_SLIP_GET_PKT_TYPE(header))
629	    {
630	    case HCI_EVENT_PKT:
631	    case HCI_ACLDATA_PKT:
632	    case HCI_ISODATA_PKT:
633	      {
634	        ret = bt_slip_hci_packet_handle(&priv->dev,
635	                                        BT_SLIP_GET_PKT_TYPE (header),
636	                                        payload, BT_SLIP_GET_LEN (header));
637	      }
638	      break;
639	    case HCI_3WIRE_LINK_PKT:
640	      {
641	        ret = bt_slip_link_packet_hanlde(priv, header, len);
642	      }
643	      break;
644	    default:
645	      {
646	        ret = -ENAVAIL;
647	      }
648	      break;
649	    }
650	
651	  return ret;
652	}
