654	static int bt_slip_open(FAR struct bt_driver_s *dev)
655	{
656	  FAR struct sliphci_s *priv;
657	  FAR struct bt_driver_s *drv;
658	  int ret;
659	
660	  DEBUGASSERT(dev != NULL);
661	
662	  priv = (FAR struct sliphci_s *)dev;
663	  drv = priv->drv;
664	
665	  ret = drv->open(drv);
666	  if (ret < 0)
667	    {
668	      return ret;
669	    }
670	
671	  bt_slip_unack_init(priv);
672	  bt_slip_send_link_control(priv, g_sync_req, sizeof(g_sync_req));
673	
674	  ret = nxsem_tickwait_uninterruptible(&priv->sem, SEC2TICK(3));
675	  if (ret == -ETIMEDOUT)
676	    {
677	      wlerr("err: bluetooth driver open timeout");
678	      goto err;
679	    }
680	
681	  return ret;
682	
683	err:
684	  bt_slip_close(dev);
685	  return ret;
686	}
