688	static int bt_slip_send(FAR struct bt_driver_s *dev,
689	                        enum bt_buf_type_e type,
690	                        FAR void *data, size_t len)
691	{
692	  FAR struct sliphci_s *priv;
693	  FAR struct unack_frame_s *frame;
694	  int ret;
695	  uint8_t var;
696	
697	  DEBUGASSERT(dev != NULL);
698	
699	  if (data == NULL)
700	    {
701	      return -EINVAL;
702	    }
703	
704	  priv = (FAR struct sliphci_s *)dev;
705	
706	  ret = nxmutex_lock(&priv->sliplock);
707	  if (ret < 0)
708	    {
709	      return ret;
710	    }
711	
712	  if (bt_slip_unack_size(priv) >= priv->txwin)
713	    {
714	      bt_slip_send_ack(priv);
715	
716	      nxmutex_unlock(&priv->sliplock);
717	      nxsem_wait_uninterruptible(&priv->sem);
718	      ret = nxmutex_lock(&priv->sliplock);
719	      if (ret < 0)
720	        {
721	          return ret;
722	        }
723	    }
724	
725	  switch (type)
726	    {
727	    case BT_CMD:
728	      var = HCI_COMMAND_PKT;
729	      break;
730	    case BT_ACL_OUT:
731	      var = HCI_ACLDATA_PKT;
732	      break;
733	    case BT_ISO_OUT:
734	      var = HCI_ISODATA_PKT;
735	      break;
736	    default:
737	      ret = -EINVAL;
738	      goto end;
739	    }
740	
741	  ret = bt_slip_send_packet(priv, var, data, len);
742	  if (ret < 0)
743	    {
744	      goto end;
745	    }
746	
747	  frame = (FAR struct unack_frame_s *)bt_slip_unack_ctor(priv);
748	  frame->type = type;
749	  frame->pktlen = len;
750	  memcpy(frame->data, data, len);
751	
752	  if (work_available(&priv->retxworker))
753	    {
754	      work_queue(HPWORK, &priv->retxworker, bt_slip_retx_work,
755	                 priv, BT_SLIP_RTX_TIMEOUT);
756	    }
757	
758	end:
759	  nxmutex_unlock(&priv->sliplock);
760	  return ret < 0 ? ret : len;
761	}
