763	/* Note: bt_slip_receive could only handle completed slip packets with
764	 * len bytes data. Avoid adding a memory copy of the data, it won't
765	 * handle this case here. you need to combine multiple incomplete slip
766	 * packets to completed slip packets from bt vendor driver.
767	 */
768	
769	static int bt_slip_receive(FAR struct bt_driver_s *drv,
770	                           enum bt_buf_type_e type,
771	                           FAR void *data, size_t len)
772	{
773	  FAR struct sliphci_s *priv = drv->priv;
774	  FAR uint8_t *packet;
775	  FAR uint8_t *cursor;
776	  FAR uint8_t *header;
777	  FAR uint8_t *pointer;
778	  uint8_t byte = 0;
779	  uint16_t checksum;
780	  size_t remaining;
781	  uint8_t state;
782	  int ret;
783	  enum
784	    {
785	      PACKET_START,
786	      PACKET_HEADER,
787	      PACKET_PAYLOAD,
788	      PACKET_DICHECK,
789	      PACKET_END,
790	    };
791	
792	  ret = nxmutex_lock(&priv->sliplock);
793	  if (ret < 0)
794	    {
795	      return ret;
796	    }
797	
798	  for (packet = data, cursor = data, header = data, state = PACKET_START;
799	       packet < (FAR uint8_t *)data + len; packet++)
800	    {
801	      switch (state)
802	        {
803	        case PACKET_START:
804	          {
805	            if (*packet == SLIP_DELIMITER)
806	              {
807	                state = PACKET_HEADER;
808	                remaining = BT_SLIP_HEADER_LEN;
809	              }
810	          }
811	          break;
812	        case PACKET_HEADER:
813	          {
814	            if (*packet == SLIP_DELIMITER)
815	              {
816	                break;
817	              }
818	
819	            pointer = bt_slip_unslip_byte(packet, &byte);
820	            if (!pointer)
821	              {
822	                state = PACKET_START;
823	                break;
824	              }
825	
826	            packet = pointer;
827	            *cursor++ = byte;
828	            remaining--;
829	
830	            if (remaining)
831	              {
832	                break;
833	              }
834	
835	            /* A packet from bt maybe consists of two H5 hci frame.
836	             */
837	
838	            header = cursor - BT_SLIP_HEADER_LEN;
839	
840	            wlinfo("rx t:%d l:%d s:%d a:%d", BT_SLIP_GET_PKT_TYPE(header),
841	                    BT_SLIP_GET_LEN(header), BT_SLIP_GET_SEQ(header),
842	                    BT_SLIP_GET_ACK(header));
843	
844	            if (!BT_SLIP_IS_HDRVALIDED(header))
845	              {
846	                wlerr("err: invalid header checksum");
847	                state = PACKET_START;
848	                break;
849	              }
850	
851	            if (BT_SLIP_IS_RELIABLE(header)
852	                && BT_SLIP_GET_SEQ(header) != priv->txack)
853	              {
854	                wlerr("err: out of order packet arrived(%u != %u)",
855	                       BT_SLIP_GET_SEQ(header), priv->txack);
856	                state = PACKET_START;
857	                break;
858	              }
859	
860	            switch (BT_SLIP_GET_PKT_TYPE(header))
861	              {
862	              case HCI_EVENT_PKT:
863	              case HCI_ACLDATA_PKT:
864	              case HCI_ISODATA_PKT:
865	              case HCI_3WIRE_LINK_PKT:
866	              case HCI_3WIRE_ACK_PKT:
867	                {
868	                  /* In DIC mode, Ack packet which has 0 byte paylod
869	                   * and has 2 byte data integrity check
870	                   */
871	
872	                  if (BT_SLIP_GET_LEN(header))
873	                    {
874	                      state = PACKET_PAYLOAD;
875	                      remaining = BT_SLIP_GET_LEN(header);
876	                    }
877	                  else if (BT_SLIP_GET_CRC(header))
878	                    {
879	                      state = PACKET_DICHECK;
880	                      remaining = BT_SLIP_CHECKSUM_LEN;
881	                    }
882	                  else
883	                    {
884	                      state = PACKET_END;
885	                      remaining = 0;
886	                    }
887	                }
888	                break;
889	              default:
890	                {
891	                  wlerr("err: packet type:%u", BT_SLIP_GET_PKT_TYPE(header));
892	                  state = PACKET_START;
893	                }
894	                break;
895	              }
896	          }
897	          break;
898	        case PACKET_PAYLOAD:
899	          {
900	            pointer = bt_slip_unslip_byte(packet, &byte);
901	            if (!pointer)
902	              {
903	                state = PACKET_START;
904	                break;
905	              }
906	
907	            packet = pointer;
908	            *cursor++ = byte;
909	            remaining--;
910	
911	            if (remaining)
912	              {
913	                break;
914	              }
915	
916	            if (BT_SLIP_GET_CRC(header))
917	              {
918	                state = PACKET_DICHECK;
919	                remaining = BT_SLIP_CHECKSUM_LEN;
920	              }
921	            else
922	              {
923	                state = PACKET_END;
924	              }
925	          }
926	          break;
927	        case PACKET_DICHECK:
928	          {
929	            pointer = bt_slip_unslip_byte(packet, &byte);
930	            if (!pointer)
931	              {
932	                state = PACKET_START;
933	                break;
934	              }
935	
936	            packet = pointer;
937	            *cursor++ = byte;
938	            remaining--;
939	
940	            if (remaining)
941	              {
942	                break;
943	              }
944	
945	            /* Remove 2 bytes crc payload, then caculate packect
946	             * checksum with packet header and body.
947	             */
948	
949	            cursor -= BT_SLIP_CHECKSUM_LEN;
950	            checksum = crc16ccittpart(header, cursor - header, 0xffff);
951	
952	            if (bt_slip_bit16_reverse(checksum) != bt_slip_get_crc(cursor))
953	              {
954	                wlerr("err: checksum(0x%04x) not match(0x%04x)", checksum,
955	                      bt_slip_get_crc(cursor));
956	                state = PACKET_START;
957	                break;
958	              }
959	
960	            state = PACKET_END;
961	          }
962	          break;
963	        case PACKET_END:
964	          {
965	            if (*packet != SLIP_DELIMITER)
966	              {
967	                wlerr("err: miss slip end");
968	                state = PACKET_START;
969	                break;
970	              }
971	
972	            bt_slip_packet_receive(priv, header, cursor - header);
973	            state = PACKET_START;
974	          }
975	          break;
976	        }
977	    }
978	
979	  nxmutex_unlock(&priv->sliplock);
980	  return packet - (FAR uint8_t *)data;
981	}
