static int bthci_init(FAR struct rtk_bt_priv_s *dev, uint8_t id)
{
  FAR struct bt_driver_s *drv = &dev->drv;
  int ret;
  wlerr("%s", __func__);
  ret = file_open(&dev->filep_uart, CONFIG_BLUETOOTH_UART_DEV, O_RDWR);
  if (ret < 0)
    {
      wlerr("fail, %s file_open ret:%d", __func__, ret);
      return ret;
    }

